// Start screen derives all project and case facts from the existing workspaces.
export function homeModel(projects=[],report=null){
 const recent=projects.filter(p=>!p.sample).slice().sort((a,b)=>String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||''))).slice(0,3);
 const variant=report?.experiments?.find(x=>x.variants?.['l2-svm'])?.variants['l2-svm'];
 return {recent,total:projects.filter(p=>!p.sample).length,case:report?{runs:report.runs?.length||0,stages:(report.runs||[]).reduce((n,r)=>n+(r.stages?.length||0),0),accuracy:typeof variant?.mean==='number'?(variant.mean*100).toFixed(2):null,levels:report.levels||{},plan:report.plan_sha256||''}:null};
}
export function renderHome({projects,report,mode,esc,icon,storageError=''}){
 const model=homeModel(projects,report),c=model.case;
 const projectStep=p=>p.presentation_review&&p.presentation_review.status!=='stale'?'demo':p.assessment?.reproduction?.job||p.run_id?'report':p.claims?.some(c=>c.confirmed)?'criteria':'materials';
 const levelRows=[['run','计划执行'],['environment_rebuilt','环境重建'],['training','论文训练协议'],['conclusion','主要结论']];
 return `<div class="start-workspace">
 <div class="start-grid"><section class="start-intro" aria-labelledby="start-title"><h2 id="start-title">一篇论文，一条证据链。</h2><p class="start-description">提交论文或代码，自动识别图表指标、审查材料，并追踪实际执行证据。</p><button class="btn primary start-primary" data-action="new">${icon('plus')}开始在线审查</button><button class="btn text" data-home-sample>先用内置样例熟悉流程 ${icon('arrow')}</button>
 <ol class="start-steps"><li><strong>准备论文与代码</strong><span>PDF、仓库地址或代码 ZIP</span></li><li><strong>自动识别审查需求</strong><span>论文自查、代码检查与复现评估</span></li><li><strong>执行并审查证据</strong><span>逐条判定，保留来源与复核记录</span></li></ol>
 <div class="start-runtime"><span class="connection-dot ${mode==='runtime'?'connected':''}"></span><div><strong>${mode==='runtime'?'本地执行已连接':'在线 API 工作台'}</strong><p>${mode==='runtime'?'可通过当前工作台提交真实核查，证据保存在本机。':'在线审查连接模型 API；适用 CPU 任务使用隔离云端环境。'}</p></div><button class="btn text" data-action="connection">${mode==='runtime'?'运行设置':'连接方式'}</button></div></section>
 <section class="start-case" aria-labelledby="start-case-title"><div class="start-case-source"><span>公开复现案例</span><span>CI 归档</span></div><h2 id="start-case-title">LIBLINEAR <span>/ news20</span></h2><p>从作者代码与公开数据，到独立重算和分层验收。</p>${c?`<dl class="start-case-facts"><div><dt>实际运行</dt><dd>${c.runs}<small> 次</small></dd></div><div><dt>阶段证据</dt><dd>${c.stages}<small> 个</small></dd></div><div><dt>L2-SVM 准确率均值</dt><dd>${c.accuracy??'未测'}${c.accuracy?'<small>%</small>':''}</dd></div></dl><div class="start-acceptance">${levelRows.map(([key,label])=>`<div><span>${label}</span><strong class="${c.levels[key]===true?'accepted':''}">${c.levels[key]===true?'证据满足':c.levels[key]===false?'尚未满足':'未知'}</strong></div>`).join('')}</div><p class="start-case-scope">采用现代作者代码与重新划分。当前覆盖 news20 的有限实验，主要结论保留未通过。</p><div class="start-case-footer"><code title="${esc(c.plan)}">计划 ${esc(c.plan.slice(0,12)||'未记录')}</code><button class="btn" data-home-case>查看案例与证据 ${icon('arrow')}</button></div>`:'<div class="start-case-unavailable"><p>公开案例暂未读取成功。</p><button class="btn" data-action="nav" data-page="workbench">进入执行中心重试</button></div>'}</section></div>
 <section class="start-recent" aria-labelledby="start-recent-title"><div class="section-heading"><div><h2 id="start-recent-title">继续我的项目</h2><p>${model.total?`${model.total} 个项目保存在当前浏览器`:'从第一篇论文开始建立你的复现记录'}</p></div><button class="btn text" data-action="nav" data-page="projects">所有论文项目 ${icon('arrow')}</button></div>${storageError?`<p class="error-box" role="alert">${esc(storageError)}</p>`:''}${model.recent.length?`<div class="start-projects">${model.recent.map(p=>`<button class="start-project" data-home-project="${esc(p.id)}" data-home-step="${projectStep(p)}"><span class="start-project-title">${esc(p.title||'未命名论文项目')}</span><span>${p.paper?.pages?.length||0} 页论文 · ${(p.claims||[]).filter(c=>c.selected&&c.confirmed).length} 条已确认主张</span><span class="start-project-next">${projectStep(p)==='demo'?'查看演示评测':projectStep(p)==='report'?'查看执行与报告':projectStep(p)==='criteria'?'继续核对复现条件':'继续准备材料'} ${icon('arrow')}</span></button>`).join('')}</div>`:`<div class="start-empty"><div><strong>还没有自己的论文项目</strong><p>新建评估后，项目、确认的主张和复核记录会在这里继续。</p></div><button class="btn" data-home-sample>打开内置样例 ${icon('arrow')}</button></div>`}</section></div>`;
}
